## 4. VFX IMPLEMENTATION PRIORITY LOGIC

### Camera Shake System (Trauma-Based)
```javascript
class CameraShake {
  constructor() {
    this.intensity = 0.0; // decays over time
    this.maxIntensity = 2.0;
    this.decayRate = 0.95; // per frame
    this.velocityScale = 1.0; // scales on impact velocity
  }

  applyImpact(velocityMagnitude) {
    // Scale shake intensity by impact severity
    const trauma = Math.min(velocityMagnitude * 0.1, this.maxIntensity);
    this.intensity += trauma * this.velocityScale;
  }

  update(deltaTime) {
    if (this.intensity > 0.01) {
      // Apply random offset to camera position
      const shakeX = (Math.random() - 0.5) * this.intensity;
      const shakeY = (Math.random() - 0.5) * this.intensity;
      this.camera.position.x += shakeX;
      this.camera.position.y += shakeY;

      // Decay intensity
      this.intensity *= this.decayRate;
    } else {
      // Return to original position via lerp
      this.camera.position.lerp(this.originalPosition, 0.1);
    }
  }

  reset() {
    this.intensity = 0.0;
    this.camera.position.copy(this.originalPosition);
  }
}
```

### Hit-Stop / Frame-Freeze System
```javascript
class HitStopManager {
  constructor() {
    this.active = false;
    this.duration = 0.0; // seconds remaining
    this.maxDuration = 0.15; // max frame freeze
    this.timescaleBuffer = 1.0; // applied to all updates
  }

  triggerImpact(impactSeverity) {
    // Severity: 0-1 (alien death=1, player hit=0.8, bullet miss=0.3)
    this.duration = impactSeverity * this.maxDuration;
    this.timescaleBuffer = 0.05; // freeze effect
    this.active = true;
  }

  update(deltaTime) {
    if (this.active) {
      this.duration -= deltaTime;
      if (this.duration <= 0) {
        this.active = false;
        this.timescaleBuffer = 1.0;
      }
      return this.timescaleBuffer; // apply to all game updates
    }
    return 1.0;
  }
}
```

### Particle Burst System (Procedural)
```javascript
class ParticleManager {
  constructor(maxParticles = 500) {
    this.particles = new Array(maxParticles).fill(null).map(() => ({
      position: new THREE.Vector3(),
      velocity: new THREE.Vector3(),
      color: new THREE.Color(),
      lifetime: 0,
      maxLifetime: 0,
      active: false
    }));
    this.activeCount = 0;

    // Material for particle system (additive blending)
    this.material = new THREE.PointsMaterial({
      size: 0.2,
      color: 0xffffff,
      transparent: true,
      opacity: 1.0,
      blending: THREE.AdditiveBlending,
      depthWrite: false
    });

    this.geometry = new THREE.BufferGeometry();
    this.particleSystem = new THREE.Points(this.geometry, this.material);
    scene.add(this.particleSystem);
  }

  spawnBurst(position, count, color) {
    for (let i = 0; i < count && this.activeCount < this.maxParticles; i++) {
      const particle = this.acquire();
      particle.position.copy(position);
      // Cone distribution for explosion effect
      const angle = Math.random() * Math.PI * 2;
      const speed = 3 + Math.random() * 5;
      particle.velocity.set(
        Math.cos(angle) * speed,
        Math.sin(angle) * speed,
        (Math.random() - 0.5) * 2 // slight Z spread
      );
      particle.color.copy(color);
      particle.lifetime = 0;
      particle.maxLifetime = 20 + Math.random() * 10;
      particle.active = true;
      this.activeCount++;
    }
  }

  update(deltaTime) {
    const positions = [];
    const colors = [];

    for (let i = 0; i < this.particles.length; i++) {
      const p = this.particles[i];
      if (!p.active) continue;

      // Update physics
      p.position.addScaledVector(p.velocity, deltaTime);
      p.lifetime += deltaTime * 60; // normalize to frames

      // Fade out near end of life
      const alpha = Math.max(0, 1 - (p.lifetime / p.maxLifetime));

      positions.push(p.position.x, p.position.y, p.position.z);
      colors.push(p.color.r * alpha, p.color.g * alpha, p.color.b * alpha);
    }

    // Update buffer attributes
    this.geometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
    this.geometry.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));
    this.geometry.attributes.position.needsUpdate = true;
    this.geometry.attributes.color.needsUpdate = true;

    // Cleanup inactive particles
    for (let i = 0; i < this.particles.length; i++) {
      if (this.particles[i].lifetime >= this.particles[i].maxLifetime) {
        this.release(i);
      }
    }
  }

  acquire(): Particle {
    // LRU strategy: find least recently used inactive particle
    for (let p of this.particles) {
      if (!p.active) return p;
    }
    return null; // pool exhausted
  }

  release(index: number) {
    this.particles[index].active = false;
    this.activeCount--;
  }

  dispose() {
    this.geometry.dispose();
    this.material.dispose();
    this.particleSystem.dispose();
  }
}
```

### Motion Trails System
```javascript
class MotionTrailManager {
  constructor(thresholdVelocity = 5.0) {
    this.trails = new Map(); // meshId → trailData
    this.thresholdVelocity = thresholdVelocity;

    // Trail geometry (reused across all trails)
    this.geometry = new THREE.BufferGeometry();
    this.material = new THREE.LineBasicMaterial({
      color: 0x00ffff,
      transparent: true,
      opacity: 0.5,
      blending: THREE.AdditiveBlending
    });

    this.trailMesh = new THREE.Line(this.geometry, this.material);
    scene.add(this.trailMesh);
  }

  addTrail(entity) {
    if (entity.velocity.length() > this.thresholdVelocity) {
      const trailData = {
        positions: [],
        timestamps: [],
        maxSegments: 20
      };
      this.trails.set(entity.id, trailData);
    }
  }

  updateTrails(deltaTime) {
    const allPositions = [];

    for (const [id, data] of this.trails.entries()) {
      // Add current position
      data.positions.push(scene.getObjectByProperty('userData', { id }).position.clone());
      data.timestamps.push(Date.now());

      // Remove old segments
      while (data.positions.length > data.maxSegments) {
        data.positions.shift();
        data.timestamps.shift();
      }
    }

    // Flatten positions for single geometry update
    for (const pos of allPositions) {
      this.geometry.setAttribute('position', new THREE.Float32BufferAttribute(
        allPositions.flatMap(p => [p.x, p.y, p.z]), 3
      ));
    }

    this.geometry.attributes.position.needsUpdate = true;
  }

  dispose() {
    this.geometry.dispose();
    this.material.dispose();
    this.trailMesh.dispose();
  }
}
```

### Shockwave Ring System
```javascript
class ShockwaveManager {
  constructor() {
    this.rings = []; // active shockwaves
    this.maxRings = 10;

    const geometry = new THREE.RingGeometry(0.5, 0.6, 32);
    const material = new THREE.MeshBasicMaterial({
      color: 0x00ffff,
      transparent: true,
      opacity: 0.8,
      side: THREE.DoubleSide,
      blending: THREE.AdditiveBlending
    });

    this.ringMesh = new THREE.Mesh(geometry, material);
    scene.add(this.ringMesh);
  }

  spawnShockwave(position) {
    if (this.rings.length >= this.maxRings) return; // cap active rings

    const ring = {
      mesh: this.ringMesh.clone(),
      position: position.clone(),
      radius: 0.5,
      speed: 3.0, // units/frame
      opacity: 1.0,
      lifetime: 60 // frames
    };

    ring.mesh.position.copy(position);
    scene.add(ring.mesh);
    this.rings.push(ring);
  }

  updateShockwaves(deltaTime) {
    for (let i = this.rings.length - 1; i >= 0; i--) {
      const ring = this.rings[i];

      // Expand radius
      ring.radius += ring.speed * deltaTime;

      // Fade out
      ring.opacity -= deltaTime * 0.02;

      if (ring.opacity <= 0) {
        scene.remove(ring.mesh);
        ring.mesh.geometry.dispose();
        ring.mesh.material.dispose();
        this.rings.splice(i, 1);
      } else {
        ring.mesh.scale.set(ring.radius / 0.5, ring.radius / 0.5, 1);
        ring.mesh.material.opacity = ring.opacity;
      }
    }
  }

  dispose() {
    this.rings.forEach(ring => {
      scene.remove(ring.mesh);
      ring.mesh.geometry.dispose();
      ring.mesh.material.dispose();
    });
    this.ringMesh.geometry.dispose();
    this.ringMesh.material.dispose();
  }
}
```

### Floating Score Text System (3D + HTML Overlay)
```javascript
class FloatingTextManager {
  constructor() {
    this.texts = []; // active floating texts
    this.maxTexts = 20;

    // 3D text container
    this.container = new THREE.Group();
    scene.add(this.container);

    // HTML overlay for crisp rendering
    this.overlay = document.createElement('div');
    this.overlay.style.cssText = `
      position: absolute;
      top: 0; left: 0;
      pointer-events: none;
      font-family: 'Courier New', monospace;
      font-weight: bold;
      text-shadow: 0 0 10px #00ffff, 0 0 20px #ff00ff;
    `;
    document.body.appendChild(this.overlay);
  }

  spawnText(position, text, points = 0) {
    if (this.texts.length >= this.maxTexts) return;

    const textData = {
      element: null, // HTML element
      mesh: null, // Three.js sprite for parallax
      position: position.clone(),
      velocity: new THREE.Vector3(0, 2.0, 0), // float upward
      lifetime: 120, // frames
      points: points
    };

    // Create HTML element
    const el = document.createElement('div');
    el.textContent = `+${points}`;
    el.style.cssText = `
      color: #ffff00;
      font-size: 24px;
      opacity: 1.0;
      transform: translate(-50%, -50%);
    `;

    // Create Three.js sprite (linked to HTML via CSS3DRenderer)
    const sprite = new THREE.Sprite(new THREE.SpriteMaterial({ 
      map: this.createTextTexture(text),
      color: 0xffff00 
    }));
    sprite.position.copy(position);
    sprite.scale.set(2, 1, 1);

    textData.element = el;
    textData.mesh = sprite;

    this.container.add(sprite);
    this.texts.push(textData);
  }

  updateTexts(deltaTime) {
    for (let i = this.texts.length - 1; i >= 0; i--) {
      const t = this.texts[i];

      // Move upward
      t.position.y += t.velocity.y * deltaTime;
      t.mesh.position.copy(t.position);

      // Fade out
      t.lifetime -= deltaTime * 60;
      const alpha = Math.max(0, t.lifetime / 120);
      t.element.style.opacity = alpha;
      t.mesh.material.opacity = alpha;

      if (t.lifetime <= 0) {
        this.container.remove(t.mesh);
        t.element.remove();
        this.texts.splice(i, 1);
      }
    }

    // Sync HTML positions to screen space
    const rendererSize = new THREE.Vector2();
    this.renderer.getSize(rendererSize);

    for (const t of this.texts) {
      const screenPos = t.mesh.position.clone().project(this.camera);
      const x = (screenPos.x * 0.5 + 0.5) * rendererSize.width;
      const y = (-screenPos.y * 0.5 + 0.5) * rendererSize.height;

      t.element.style.left = `${x}px`;
      t.element.style.top = `${y}px`;
    }
  }

  createTextTexture(text): THREE.CanvasTexture {
    const canvas = document.createElement('canvas');
    canvas.width = 256; canvas.height = 64;
    const ctx = canvas.getContext('2d');

    ctx.fillStyle = 'transparent';
    ctx.fillRect(0, 0, 256, 64);

    ctx.font = 'bold 32px Courier New';
    ctx.fillStyle = '#ffff00';
    ctx.textAlign = 'center';
    ctx.fillText(text, 128, 40);

    return new THREE.CanvasTexture(canvas);
  }

  dispose() {
    this.container.clear();
    this.overlay.remove();
  }
}
```

